/** Tax on amounts and on invoice lines. Rates are integer basis points. */

import { assertMinorUnits } from '../core/money.mjs';
import { scaleRounded } from '../core/rounding.mjs';
import { assertBasisPoints } from '../core/validate.mjs';

export function groupByRate(lines) {
  const groups = new Map();
  lines.forEach((line, position) => {
    assertBasisPoints(line.taxRateBps, 'Tax rate');
    if (!groups.has(line.taxRateBps)) groups.set(line.taxRateBps, []);
    groups.get(line.taxRateBps).push({ line, position });
  });
  return groups;
}

export function taxableAmount(members) {
  return members.reduce((total, { line }) => total + line.net, 0);
}

const BASIS_POINTS = 10_000;
const BASIS_POINTS_BIG = 10_000n;

/** Tax on a net amount at a rate. */
export function taxForAmount(net, rateBps) {
  assertMinorUnits(net);
  assertBasisPoints(rateBps, 'Tax rate');
  return scaleRounded(net, rateBps, BASIS_POINTS);
}

/**
 * Spreads the tax due on one rate group over its lines. Each line gets its
 * exact tax rounded down, and the units still needed to reach the group's tax
 * go to the lines with the largest fractions, so every line stays within one
 * unit of its own exact tax and the lines add up to the group's tax.
 */
function spreadGroupTax(members, rateBps) {
  const due = taxForAmount(taxableAmount(members), rateBps);
  const exact = members.map(({ line }) => BigInt(line.net) * BigInt(rateBps));
  const floors = exact.map((value) => {
    const quotient = value / BASIS_POINTS_BIG;
    return value % BASIS_POINTS_BIG < 0n ? quotient - 1n : quotient;
  });
  const fractions = exact.map((value, position) => value - floors[position] * BASIS_POINTS_BIG);
  const shares = floors.map(Number);
  let leftover = due - shares.reduce((total, share) => total + share, 0);
  const order = members
    .map((_, position) => position)
    .filter((position) => fractions[position] > 0n)
    .sort((a, b) => (fractions[b] > fractions[a] ? 1 : fractions[b] < fractions[a] ? -1 : a - b));
  for (const position of order) {
    if (leftover <= 0) break;
    shares[position] += 1;
    leftover -= 1;
  }
  return shares;
}

/**
 * Adds `tax` and `gross` to each discounted line. The tax is worked out per
 * rate on the sum of the nets at that rate, rounded once, then spread over the
 * lines at that rate.
 */
export function applyTax(lines) {
  const taxes = new Array(lines.length).fill(0);
  for (const [rateBps, members] of groupByRate(lines)) {
    const shares = spreadGroupTax(members, rateBps);
    members.forEach(({ position }, index) => {
      taxes[position] = shares[index];
    });
  }
  return lines.map((line, position) => ({
    ...line,
    tax: taxes[position],
    gross: line.net + taxes[position],
  }));
}

/** One row per rate: the taxable amount and the tax due on it. */
export function taxSummary(lines) {
  const rows = [];
  for (const [rateBps, members] of groupByRate(lines)) {
    const taxable = taxableAmount(members);
    rows.push({ rateBps, taxable, tax: taxForAmount(taxable, rateBps) });
  }
  return rows;
}
